"use strict";
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve('outputs/qwen-image-migration-20261105'),r=JSON.parse(fs.readFileSync(path.join(root,'report.json'),'utf8'));
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isFinite(n)?'¥'+n.toFixed(2):'—';
const images=r.cases.filter(c=>c.imageFile),allCost=r.cases.reduce((a,c)=>a+(c.supplierEstimateCny||0),0);
const decision=r.acceptance?.decision||'正在验收，尚未切换客户线路';
const cards=r.cases.map(c=>`<article><header><span class="tag">${h(c.model)}</span><h2>${h(c.name)}</h2><p class="muted">${h(c.id)} · ${h(c.status)}</p></header>${c.imageFile?`<a href="qwen-image-migration-20261105/${h(c.imageFile)}" target="_blank"><img loading="lazy" src="qwen-image-migration-20261105/${h(c.imageFile)}" alt="${h(c.name)}"></a>`:`<p class="failure">${h(c.error||'处理中')}</p>`}<div class="stats"><span>${money(c.supplierEstimateCny)}<small>供应商公开价估算</small></span><span>${c.ms?Math.round(c.ms/1000)+' 秒':'—'}<small>接口耗时，不含前置规划</small></span><span>${c.dimensions?h(c.dimensions.w+' × '+c.dimensions.h):'—'}<small>实际成品尺寸</small></span></div><p>${c.mode==='composition'?'准确文字由现有服务端排版器渲染；模型只生成视觉素材。':'模型原生生成完整画面，文字需逐字复核。'}</p>${c.planning?`<p>长上下文：${c.planning.retainedMessages} 条 / ${c.planning.sentContextChars.toLocaleString()} 字符；定稿 ${c.planning.copyChars} 字；前置规划 ${Math.round(c.planning.planMs/1000)} 秒。</p>`:''}<p class="review">${h(c.visualReview||'尚未完成目视验收，不代表商业交付通过。')}</p>${c.artworkFile?`<a href="qwen-image-migration-20261105/${h(c.artworkFile)}" target="_blank">查看模型原始素材</a>`:''}<details><summary>文案、自动检查与限制</summary><pre>${h(c.copy||'无文案')}</pre><pre>${h(JSON.stringify({planning:c.planning,ocrRequired:c.ocrRequired,usage:c.usage},null,2))}</pre><p>OCR有误识别，不能将未命中直接判为错字，也不能将命中视作全图正确。</p></details></article>`).join('');
const body=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BossAI · 千问迁移实测</title><style>*{box-sizing:border-box}body{margin:0;background:#101722;color:#e7eef8;font:16px/1.75 'Microsoft YaHei',sans-serif}main{max-width:1480px;margin:auto;padding:28px}h1{font-size:28px;line-height:1.45}h2{font-size:21px;line-height:1.5;margin:12px 0 4px}p{margin:12px 0}.intro,article,.panel{background:#192535;border:1px solid #34465d;border-radius:18px;padding:24px;margin-bottom:22px}.intro{border-top:4px solid #62b5ee}.decision{font-size:20px;color:#a7dcff}.muted,small{color:#a7b7ca}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}article{min-width:0;margin:0}img{display:block;width:100%;height:570px;object-fit:contain;background:#0b111a;border-radius:10px}.tag{display:inline-block;color:#8eddd0;background:#163c3d;border:1px solid #38716f;border-radius:20px;padding:3px 12px;font-size:13px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:18px 0}.stats span{font-size:20px;color:#9fd8ff;font-variant-numeric:tabular-nums}.stats small{display:block;font-size:12px;line-height:1.5;margin-top:6px}.review{border-left:3px solid #7aaed4;padding-left:14px}.failure{background:#492a2c;padding:18px;border-radius:10px}a,summary{color:#9bd5ff}summary{cursor:pointer;margin-top:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#101a28;padding:14px;font:13px/1.8 'Microsoft YaHei',sans-serif;border-radius:10px}.limits li{margin:12px 0}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{padding:12px;text-align:left;border-bottom:1px solid #34465d}th{color:#9fd8ff}@media(max-width:850px){main{padding:14px}.grid{grid-template-columns:1fr}img{height:auto;max-height:850px}.stats{gap:8px}.stats span{font-size:18px}}</style><main><section class="intro"><p class="muted">BossAI · 服务端供应商迁移隔离验收 · 2026-11-05</p><h1>千问 Image 3.0 / Pro，是否能替换当前作图线路？</h1><p class="decision">${h(decision)}</p><p>已生成 ${images.length} 张实测图，供应商公开价估算合计 ${money(allCost)}。未扣正式客户额度；不是平台最终结算账单。</p><p>本页区分：接口成功、上下文理解、文字准确、视觉质量、功能兼容。某一项通过不能替代其他项。</p><p>${h(r.acceptance?.summary||r.scope)}</p></section><section class="panel"><h2>已经确认的能力边界</h2><ul class="limits"><li>千问 3.0 系列最多输入 3 张参考图；当前线路有四张原图契约，不能静默丢掉其中一张。</li><li>千问输出比例范围 1:8～8:1；9:1 等现有长条画布不能直接迁移。</li><li>本轮官方 API 未提供与 Seedream 相同的原生图层拆分契约，不能把“支持编辑”当作“功能完全等价”。</li><li>标准版公开价为 ¥0.18/输出张；Pro 小图 ¥0.25、大图 ¥0.50；每张参考图另计 ¥0.02。按当前台账估算，需用实际路由占比核算收益。</li></ul><p><a href="https://help.aliyun.com/zh/model-studio/qwen-image-generation-and-editing-api-reference">官方接口与能力限制</a> · <a href="https://help.aliyun.com/zh/model-studio/model-pricing">官方价格</a></p></section>${r.planningErrors?.length?`<section class="panel"><h2>保留的长上下文失败记录</h2><pre>${h(JSON.stringify(r.planningErrors,null,2))}</pre><p>这是现有前置聊天路径的真实失败，尚未发送图片模型。不能归因于千问生图，也不能从验收中抹掉。</p></section>`:''}<section class="grid">${cards}</section><section class="panel" style="margin-top:24px"><h2>验收范围</h2><p>所有业务资料和人物均为合成测试数据。长上下文重放沿用旧 App 的最近 40 条 / 48,000 字符选择；部分历史摘要由测试夹具提供，不代表实际跨会话召回已通过。当前设备不在手边，这不是客户真机 UIKit 验收。</p><p>保留原始请求、模型返回计量、前置定稿、OCR与失败记录。点击图片查看原尺寸。</p></section></main></html>`;
const target=path.resolve('outputs/BossAI-千问Image迁移多场景验收-20261105.html');fs.writeFileSync(target,body);console.log(JSON.stringify({file:target,images:images.length,costEstimate:allCost,status:r.status}));
